// b12o1 is the order-1 part of block phhhh,pphhhhh, <a,i,j,k,l|M|b,c,m,n,o,i1,j1>.
func (el *Elem) b12o1(a, i, j, k, l, b, c, m, n, o, i1, j1 int) float64 {
	var v float64
	// (1)
	v += el.b12o1g0(a, i, j, k, l, b, c, m, n, o, i1, j1)
	return v
}

// B12 is block phhhh,pphhhhh of the secular matrix,
// <a,i,j,k,l|M|b,c,m,n,o,i1,j1>, summed over the orders the scheme keeps.
func (el *Elem) B12(a, i, j, k, l, b, c, m, n, o, i1, j1 int) float64 {
	var v float64
	if el.maxOrder[4] >= 1 {
		v += el.b12o1(a, i, j, k, l, b, c, m, n, o, i1, j1)
	}
	return v
}
